                    Some("2 road"),
                    Some("Individual"),
                    None,
                    Donor,
                ),
            ],
        ),
        (
            "fuzzy_payer",
            vec![
                observation(1, Some("John Smith"), Some("1 road"), None, None, Payer),
                observation(2, Some("Jon Smith"), None, None, None, Payer),
            ],
        ),
        (
            "executive_annotation",
            vec![
                observation(
                    1,
                    Some("HSBC UK (Ian Stuart, CEO)"),
                    Some("1 centenary square"),
                    Some("Company"),
                    None,
                    Donor,
                ),
                observation(
                    2,
                    Some("HSBC UK Bank plc"),
                    Some("1 centenary square"),
                    None,
                    None,
                    Payer,
                ),
