                ),
                observation(2, Some("Fletchers"), None, None, None, Payer),
            ],
        ),
        (
            "trade_union",
            vec![
                observation(
                    1,
                    Some("Unite the Union"),
                    None,
                    Some("Trade Union"),
                    None,
                    Donor,
                ),
                observation(
                    2,
                    Some("East Midlands Unite"),
                    None,
