                    Donor,
                ),
                observation(
                    3,
                    Some("United Against Hunger"),
                    None,
                    Some("Company"),
                    None,
                    Donor,
                ),
            ],
        ),
        (
            "shared_address",
            vec![
                observation(
                    1,
                    Some("Carlton Club"),
                    Some("1 road"),
                    Some("Company"),
                    None,
                    Donor,
                ),
                observation(
                    2,
                    Some("Carlton Club Political Committee"),
                    Some("1 road"),
                    Some("Company"),
                    None,
                    Donor,
                ),
