                observation(
                    2,
                    Some("John Smith"),
                    Some("1 road"),
                    Some("Company"),
                    None,
                    Donor,
                ),
            ],
        ),
        (
            "withheld",
            vec![
                observation(1, Some("Withheld"), None, None, None, Donor),
                observation(2, None, None, None, None, Payer),
